// Lê o evento da uazapi e decide se ele entra no fluxo de feedback.
// Devolve UM item com o que importa, ou nenhum item (o fluxo para aqui).
const body = ($input.first().json || {}).body || {};
const m = body.message || {};
const chat = body.chat || {};
const parar = [];

if (body.EventType !== 'messages') return parar;
// Grupo, mensagem do próprio número (o dono no celular) e a resposta
// automática (enviada pela API) não entram.
if (m.isGroup === true || String(m.chatid || '').endsWith('@g.us')) return parar;
if (m.fromMe === true || m.wasSentByApi === true) return parar;
// Edição de uma mensagem já enviada não é mensagem nova.
if (typeof m.edited === 'string' && m.edited.trim() !== '') return parar;

const token = String(body.token || '').trim();
const baseUrl = String(body.BaseUrl || '').trim().replace(/\/+$/, '');
const messageId = String(m.messageid || m.id || '').replace(/"/g, '').trim();
if (!token || !/^https:\/\//i.test(baseUrl) || !messageId) return parar;

// Telefone do cliente: a conversa individual (...@s.whatsapp.net).
const jid = [m.chatid, chat.wa_chatid, m.sender_pn]
  .map((v) => String(v || ''))
  .find((v) => v.endsWith('@s.whatsapp.net'));
if (!jid) return parar;
const telefone = jid.split('@')[0].replace(/\D/g, '');
if (telefone.length < 10 || telefone.length > 15) return parar;

const tipoMsg = String(m.messageType || '');
const midia = String(m.mediaType || '').toLowerCase();
const textoDe = (v) => (typeof v === 'string' ? v : '');
let tipo = null;
let texto = '';
if (tipoMsg === 'AudioMessage' || midia === 'ptt' || midia === 'audio') {
  tipo = 'audio';
} else if (tipoMsg === 'Conversation' || tipoMsg === 'ExtendedTextMessage' || (!tipoMsg && m.type === 'text')) {
  tipo = 'texto';
  texto = textoDe(m.text) || textoDe(m.content);
} else if (tipoMsg === 'ImageMessage' || tipoMsg === 'VideoMessage') {
  // Foto ou vídeo: só a legenda conta (ex.: foto do prato + "veio frio").
  tipo = 'texto';
  texto = textoDe(m.text);
}
// Figurinha, reação, documento, localização, contato, enquete: não entram.
texto = texto.trim();
if (!tipo || (tipo === 'texto' && !texto)) return parar;

return [{
  json: {
    token,
    baseUrl,
    messageId,
    telefone,
    tipo,
    texto: texto.slice(0, 4000),
    nomeContato: String(chat.name || m.senderName || '').trim(),
  },
}];

// A conta pode receber feedback agora? O restaurante foi achado pelo token
// da instância (o número do WhatsApp no cadastro pode estar vazio). Precisa:
// onboarding completo, assinatura ativa e conta não excluída.
const r = $input.first().json || {};
if (!r.id) return [];
if (r.excluida_em) return [];
if (r.onboarding_completo !== true) return [];
if (r.assinatura_status !== 'ativa') return [];
if (!r.whatsapp_token) return [];

const msg = $('Lê a mensagem').first().json;
return [{
  json: {
    ...msg,
    restauranteId: r.id,
    // Número de contato/suporte das Configurações (só dígitos) — nulo = não indicar.
    telefoneContato: String(r.telefone_contato || '').replace(/\D/g, '') || null,
    tokenRestaurante: r.whatsapp_token,
  },
}];

// Áudio transcrito vira texto como qualquer outra mensagem. Se o download ou
// a transcrição falharam, o fluxo para em silêncio (não há o que analisar).
const t = String(($input.first().json || {}).text || '').trim();
if (!t) return [];
const base = $('Restaurante ativo?').first().json;
return [{ json: { ...base, texto: t.slice(0, 4000) } }];

// Junta as mensagens que a pessoa mandou em sequência.
// Cada mensagem espera 20 s; só segue quem for a ÚLTIMA da conversa naquele
// momento — se chegou outra depois, é ela que vai juntar tudo.
const meu = $('Guarda no buffer').first().json;
const linhas = $input.all()
  .map((i) => i.json || {})
  .filter((r) => r.id != null && r.remote_id === meu.remote_id);
if (!linhas.length) return [];

linhas.sort((a, b) => Number(a.id) - Number(b.id));
const ultima = linhas[linhas.length - 1];
if (Number(ultima.id) !== Number(meu.id)) return [];

// A uazapi às vezes entrega o mesmo evento duas vezes: tira as repetidas.
const vistos = new Set();
const textos = [];
for (const r of linhas) {
  let d = r.message_data;
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
  if (!d || typeof d !== 'object') d = {};
  if (d.messageid) {
    if (vistos.has(d.messageid)) continue;
    vistos.add(d.messageid);
  }
  const t = String(r.message_content || '').trim();
  if (t) textos.push(t);
}
const textoCompleto = textos.join('\n').slice(0, 6000).trim();
if (!textoCompleto) return [];

const base = $('Restaurante ativo?').first().json;
return [{ json: { ...base, textoCompleto, ateId: Number(ultima.id), remoteId: meu.remote_id } }];

// O "Limpa o buffer" devolve uma linha por mensagem apagada; daqui em
// diante o fluxo segue com UM item só (a conversa juntada).
return [{ json: $('Sou a última mensagem?').first().json }];

// Valida o que a IA devolveu e decide: o que gravar e o que responder.
// Regras:
//   - Feedback (há pelo menos um ponto)  -> grava e agradece.
//   - Pergunta/pedido sobre o restaurante -> encaminha para o número de
//     contato das Configurações (sem número: só avisa que o canal é de feedback).
//   - Feedback + pergunta                 -> agradece e encaminha, numa mensagem só.
//   - Qualquer outra coisa (saudação sozinha, "obrigado", assunto fora do
//     restaurante)                         -> não responde.
const base = $('Sou a última mensagem?').first().json;

const CATEGORIAS = ['Comida', 'Bebidas', 'Atendimento', 'Ambiente', 'Limpeza', 'Preço', 'Tempo de Espera',
  'Reserva', 'Estacionamento', 'Acessibilidade', 'Música/Som', 'Cardápio/Variedade', 'Higiene', 'Outros'];
const semAcento = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

// 1. A resposta da IA vira objeto (aceita texto com ```json em volta).
const saida = $input.first().json || {};
const bruto = saida.text != null ? saida.text : saida.output != null ? saida.output : '';
let r = null;
if (bruto && typeof bruto === 'object') {
  r = bruto;
} else {
  const s = String(bruto).replace(/```json|```/g, '').trim();
  try {
    r = JSON.parse(s);
  } catch (e) {
    const achado = s.match(/\{[\s\S]*\}/);
    if (achado) {
      try { r = JSON.parse(achado[0]); } catch (e2) { r = null; }
    }
  }
}
if (Array.isArray(r)) r = { tipo: 'feedback', tem_pergunta_restaurante: false, assunto_pergunta: '', pontos: r };
if (!r || typeof r !== 'object') {
  // Sem formato não dá para gravar nem responder com segurança: a execução
  // fica marcada como erro no n8n para alguém ver.
  throw new Error('A IA devolveu algo fora do formato: ' + String(bruto).slice(0, 300));
}

// 2. Pontos válidos: categoria da lista fixa e um dos 4 sentimentos.
const sentimentoDoPonto = (valor) => {
  const v = semAcento(valor);
  if (v.includes('negativ')) return 'Negativo';
  if (v.includes('sugest')) return 'Sugestão';
  if (v.includes('positiv')) return 'Positivo';
  if (v.includes('neutr')) return 'Neutro';
  return null;
};
const pontos = [];
for (const p of Array.isArray(r.pontos) ? r.pontos : []) {
  if (!p || typeof p !== 'object') continue;
  const sentimento = sentimentoDoPonto(p.sentimento);
  if (!sentimento) continue;
  const categoria = CATEGORIAS.find((c) => semAcento(c) === semAcento(p.categoria)) || 'Outros';
  const texto = String(p.feedback_original || '').trim();
  const resumo = String(p.resumo || '').trim();
  if (!texto && !resumo) continue;
  pontos.push({
    texto_original: (texto || resumo).slice(0, 1000),
    categoria,
    sentimento,
    resumo: (resumo || texto).slice(0, 120),
  });
}

// 3. Sentimento da mensagem inteira (mesma ordem da feedbacks_originais_view):
//    positivo e negativo > negativo > positivo > sugestão > neutro.
const tem = (s) => pontos.some((p) => p.sentimento === s);
let sentimentoGeral = null;
if (pontos.length) {
  if (tem('Positivo') && tem('Negativo')) sentimentoGeral = 'Positivo e Negativo';
  else if (tem('Negativo')) sentimentoGeral = 'Negativo';
  else if (tem('Positivo')) sentimentoGeral = 'Positivo';
  else if (tem('Sugestão')) sentimentoGeral = 'Sugestão';
  else sentimentoGeral = 'Neutro';
}
const ehFeedback = pontos.length > 0;
const tipo = semAcento(r.tipo);
const temPergunta = tipo === 'pergunta_restaurante' || r.tem_pergunta_restaurante === true;

// 4. O texto da resposta.
const sortear = (lista) => lista[Math.floor(Math.random() * lista.length)];
const AGRADECIMENTOS = {
  positivo: [
    'Muito obrigado pelo seu feedback! Ficamos muito felizes em saber que você teve uma boa experiência conosco. Esperamos vê-lo novamente em breve!',
    'Agradecemos muito por compartilhar sua opinião! É um prazer saber que você gostou da sua experiência no nosso restaurante. Volte sempre!',
    'Que alegria receber seu comentário! Ficamos muito satisfeitos em saber que tudo correu bem. Obrigado por escolher a gente!',
  ],
  negativo: [
    'Agradecemos muito pelo seu feedback. Lamentamos que sua experiência não tenha sido como esperávamos, e já estamos avaliando internamente os pontos mencionados para melhorar cada vez mais.',
    'Obrigado por compartilhar sua opinião conosco. Pedimos desculpas pelos pontos que não atenderam suas expectativas — sua mensagem já está sendo levada em conta pela nossa equipe para que possamos melhorar.',
    'Sentimos muito que sua experiência não tenha sido ideal. Seu comentário é muito importante e já está sendo considerado pela nossa equipe, que está trabalhando para melhorar cada vez mais.',
  ],
  misto: [
    'Agradecemos muito pelo seu feedback detalhado! Ficamos felizes com os pontos positivos e, ao mesmo tempo, já estamos avaliando internamente o que pode melhorar. Sua opinião é muito importante para nós.',
    'Muito obrigado por compartilhar sua experiência com tantos detalhes. Ficamos contentes com o que deu certo e já estamos atentos aos pontos que precisam de atenção, buscando sempre melhorar.',
    'Obrigado pelo seu retorno completo! Levamos tanto os elogios quanto as críticas muito a sério, e já estamos trabalhando para aprimorar o que for necessário.',
  ],
  neutro: [
    'Agradecemos por compartilhar sua opinião conosco! Seu feedback é muito importante para que possamos entender cada vez melhor a experiência dos nossos clientes.',
    'Obrigado pelo seu comentário! Toda opinião nos ajuda a melhorar continuamente a experiência no nosso restaurante.',
    'Muito obrigado por dedicar um tempo para nos dar seu retorno. Ele será levado em consideração pela nossa equipe.',
  ],
  sugestao: [
    'Muito obrigado pela sua sugestão! Ela já foi registrada e vai ser avaliada com carinho pela nossa equipe.',
    'Agradecemos a sugestão! Ideias como a sua nos ajudam a melhorar sempre — já repassamos para a nossa equipe.',
    'Obrigado por compartilhar sua sugestão conosco! Ela foi anotada e será levada em consideração pela nossa equipe.',
  ],
};
const CENARIO = {
  'Positivo e Negativo': 'misto',
  Negativo: 'negativo',
  Positivo: 'positivo',
  'Sugestão': 'sugestao',
  Neutro: 'neutro',
};

const contato = base.telefoneContato ? String(base.telefoneContato).replace(/\D/g, '') : '';
const contatoComPais = contato ? (contato.length <= 11 ? '55' + contato : contato) : '';
const formatar = (t) => {
  let d = t;
  if ((d.length === 12 || d.length === 13) && d.startsWith('55')) d = d.slice(2);
  if (d.length === 10) return '(' + d.slice(0, 2) + ') ' + d.slice(2, 6) + '-' + d.slice(6);
  if (d.length === 11) return '(' + d.slice(0, 2) + ') ' + d.slice(2, 7) + '-' + d.slice(7);
  return t;
};
const assunto = String(r.assunto_pergunta || '').trim().replace(/[.!?;:]+$/, '');
const sobre = assunto || 'esse assunto';
const encaminhar = (comeco) => contatoComPais
  ? comeco + ' não consigo te ajudar com ' + sobre + ' por aqui. Para isso, fale com a gente pelo WhatsApp '
    + formatar(contatoComPais) + ': https://wa.me/' + contatoComPais
  : comeco + ' não consigo te ajudar com ' + sobre + ' por aqui.';

let resposta = '';
if (ehFeedback) {
  const cenario = CENARIO[sentimentoGeral];
  resposta = sortear(AGRADECIMENTOS[cenario]);
  if (cenario !== 'sugestao' && tem('Sugestão')) resposta += ' Anotamos também a sua sugestão.';
  if (temPergunta) resposta += '\n\n' + encaminhar('Sobre a sua pergunta: este número é só para receber opiniões, então');
} else if (temPergunta) {
  resposta = encaminhar('Este número é só para receber a sua opinião sobre a experiência no restaurante, então');
}

return [{
  json: {
    restauranteId: base.restauranteId,
    telefone: base.telefone,
    baseUrl: base.baseUrl,
    tokenRestaurante: base.tokenRestaurante,
    textoCompleto: base.textoCompleto,
    tipoIA: tipo,
    ehFeedback,
    temPergunta,
    sentimentoGeral,
    pontos,
    resposta,
  },
}];

// Um item por ponto, já ligado à mensagem original que acabou de ser salva.
const r = $('Monta a resposta').first().json;
const origemId = ($input.first().json || {}).id;
if (!origemId) throw new Error('A mensagem original não foi salva (sem id).');
return r.pontos.map((p) => ({
  json: {
    texto_original: p.texto_original,
    categoria: p.categoria,
    sentimento: p.sentimento,
    resumo: p.resumo,
    telefone_cliente: r.telefone,
    restaurante_id: r.restauranteId,
    origem_id: origemId,
  },
}));
